from hashlib import sha256
import json

records = {}
def create_job(key, payload):
    digest = sha256(json.dumps(payload, sort_keys=True).encode()).hexdigest()
    if key in records:
        old_digest, result = records[key]
        if digest != old_digest:
            raise ValueError("key reused with different payload")
        return result
    result = {"job_id": len(records) + 1, "status": "accepted"}
    records[key] = (digest, result)
    return result

