def response_state(retrieved, supported, failed=False):
    if failed:
        return {"state": "error", "message": "Search failed; retry or use manual search."}
    if not retrieved:
        return {"state": "empty", "message": "No accessible evidence was found."}
    if not supported:
        return {"state": "abstain", "message": "Evidence does not support an answer."}
    return {"state": "answer", "citations": [r["id"] for r in retrieved]}

