print(lower_bound([], 3))

async function main() {
  let latest = 0;
  let visible = "";
  const pending = [];
  function search(query) {
    const requestId = ++latest;
    let resolve;
    const promise = new Promise(function(done) { resolve = done; });
    pending.push({query, resolve});
    return promise.then(function(result) {
      if (requestId === latest) visible = result;
    });
  }
